<?php
declare(strict_types=1);
require __DIR__.'/../lib/bootstrap.php';
$admin=require_admin();
header('Cache-Control: no-store');header('X-Frame-Options: DENY');header('X-Content-Type-Options: nosniff');header('X-Robots-Tag: noindex, nofollow');
$view=(string)($_GET['view']??'builder');if(!in_array($view,['builder','design','kits','home'],true))$view='builder';
require_permission($view==='home'?'manage_settings':($view==='design'?'manage_themes':'manage_pages'));
require_once __DIR__.'/../lib/studio-home.php';
$error='';$message=flash();$id=max(0,(int)($_GET['id']??0));
$row=['id'=>0,'title'=>'Nowa strona','slug'=>'','content'=>le_studio_json(['schema'=>1,'blocks'=>[]]),'content_format'=>'blocks','edit_version'=>1,'status'=>'draft','publish_at'=>null,'show_in_menu'=>0,'menu_order'=>0,'seo_title'=>'','seo_description'=>''];
if($id){$row=le_content_row('page',$id);if(!$row||$row['deleted_at']!==null){http_response_code(404);exit('Nie znaleziono strony.');}if($row['content_format']!=='blocks'){http_response_code(400);exit('Ta strona korzysta z edytora tekstowego. Wróć do Podstron, aby ją edytować.');}}
$design=le_studio_saved_design();$designRaw=setting('studio_design','{}');$designRevision=hash('sha256',$designRaw);
$presetsRaw=setting('studio_presets','{}');$presets=json_decode($presetsRaw,true)?:[];
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        if(!csrf_ok())throw new RuntimeException('Sesja formularza wygasła. Odśwież stronę.');
        $action=(string)($_POST['action']??'');
        if($action==='preview'||$action==='layout_import'){
            header('Content-Type: application/json; charset=utf-8');
            try{if($action==='layout_import')require_permission('manage_pages');$doc=$action==='layout_import'?le_studio_import((string)($_POST['layout']??'')):le_studio_document((string)($_POST['content']??''));$d=le_studio_design(json_decode((string)($_POST['design']??'{}'),true,32,JSON_THROW_ON_ERROR));echo json_encode(['ok'=>true,'document'=>$doc,'html'=>le_studio_preview(le_studio_json($doc),$d)],JSON_THROW_ON_ERROR);}catch(Throwable $e){http_response_code(400);echo json_encode(['ok'=>false,'error'=>$e->getMessage()]);}exit;
        }
        if($action==='home_save'){le_studio_save_home($_POST);flash('Strona główna została zapisana.');redirect('/admin/studio.php?view=home');}
        if($action==='page_save'){
            require_permission('manage_pages');if((int)($_POST['id']??0)!==$id)throw new RuntimeException('Niezgodny identyfikator strony.');
            $fields=$_POST;$fields['kind']='page';$fields['content_format']='blocks';$fields['content']=le_studio_json(le_studio_document((string)($fields['content']??'')));
            // Preserve submitted content on validation/concurrency errors.
            $saved=le_content_save('page',$fields);flash('Strona zapisana.');redirect('/admin/studio.php?id='.$saved.'&saved=1');
        }elseif($action==='kit_create'){
            require_permission('manage_pages');$ids=le_studio_create_kit((string)($_POST['kit']??''));flash('Utworzono 3 strony w szkicach. Dostosuj treści i opublikuj je, gdy będą gotowe.');redirect('/admin/studio.php?id='.$ids[0]);
        }elseif($action==='design_save'||$action==='preset_save'||$action==='preset_delete'){
            require_permission('manage_themes');$design=le_studio_design($_POST);
            $pdo=db();$pdo->beginTransaction();
            try{
                // Serialize first use and compare the saved revision under the same lock.
                $pdo->prepare("INSERT IGNORE INTO settings(setting_key,setting_value) VALUES('studio_design','{}')")->execute();
                $q=$pdo->prepare("SELECT setting_value FROM settings WHERE setting_key='studio_design' FOR UPDATE");$q->execute();$locked=(string)$q->fetchColumn();
                if(!hash_equals(hash('sha256',$locked),(string)($_POST['design_revision']??'')))throw new RuntimeException('Wygląd zmienił się w innym oknie. Odśwież przed zapisem.');
                if($action==='design_save'){set_setting('studio_design',le_studio_json($design));set_setting('studio_enabled',!empty($_POST['enabled'])?'1':'0');}
                else{
                    $q=$pdo->prepare("SELECT setting_value FROM settings WHERE setting_key='studio_presets' FOR UPDATE");$q->execute();$p=json_decode((string)($q->fetchColumn()?:'{}'),true)?:[];
                    $name=le_studio_string($_POST['preset_name']??'',60);if($name==='')throw new RuntimeException('Podaj nazwę wariantu.');
                    if($action==='preset_delete')unset($p[$name]);else{if(!isset($p[$name])&&count($p)>=20)throw new RuntimeException('Maksymalnie 20 wariantów.');$p[$name]=$design;}
                    set_setting('studio_presets',le_studio_json($p));
                }$pdo->commit();
            }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
            audit_log('studio.'.$action,'theme',null);flash('Zapisano ustawienia Studio.');redirect('/admin/studio.php?view=design');
        }elseif($action==='home_set'){
            require_permission('manage_settings');require_permission('manage_pages');
            $home=(int)($_POST['home_id']??0);$pdo=db();$pdo->beginTransaction();
            try{if($home){$p=le_content_row('page',$home,true);if(!$p||$p['status']!=='published'||$p['deleted_at']!==null)throw new RuntimeException('Najpierw opublikuj wybraną stronę.');}set_setting('studio_home_page',(string)$home);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
            audit_log('studio.home_set','page',(string)$home);flash($home?'Ustawiono stronę główną.':'Przywrócono dotychczasową stronę główną.');redirect('/admin/studio.php?id='.$id);
        }else throw new RuntimeException('Nieznana operacja.');
    }catch(Throwable $e){$error=$e->getMessage();if(($_POST['action']??'')==='home_save')$homeValues=$_POST;if(in_array($_POST['action']??'',['preview','layout_import'],true)){header('Content-Type: application/json; charset=utf-8');http_response_code(400);echo json_encode(['ok'=>false,'error'=>$error]);exit;}if(($_POST['action']??'')==='page_save')foreach(['title','slug','content','status','publish_at','edit_version','seo_title','seo_description','menu_order'] as $key)if(isset($_POST[$key])&&is_string($_POST[$key]))$row[$key]=$_POST[$key];if(($_POST['action']??'')==='page_save')$row['show_in_menu']=!empty($_POST['show_in_menu']);}
}
$pages=[];if(has_permission('manage_pages',$admin))$pages=db()->query("SELECT id,title,content_format,status FROM pages WHERE deleted_at IS NULL ORDER BY updated_at DESC LIMIT 200")->fetchAll();
try{$doc=$view==='builder'?le_studio_document($row['content']):le_studio_kit('company');}catch(Throwable $invalid){$doc=['schema'=>1,'blocks'=>[]];$error=$error?:$invalid->getMessage();}
$kits=[];foreach(le_studio_kit_names() as $key=>$name)$kits[$key]=le_studio_kit($key);
$studioMessages=[];foreach(le_catalog('pl') as $key=>$source)if(str_starts_with($key,'ui.'))$studioMessages[$source]=__($key);
$boot=['messages'=>$studioMessages,'page'=>$id,'baseVersion'=>(int)$row['edit_version'],'user'=>(int)$admin['id'],'media'=>has_permission('manage_media',$admin),'document'=>$doc,'design'=>($view==='design'||setting('studio_enabled','0')==='1'?$design:le_studio_design([])),'types'=>le_studio_types(),'kits'=>$kits,'presets'=>$presets];
